---build---
build_dir=$WORK/build
mkdir -p ${build_dir}
pushd ${build_dir}
rm -rf ./*
if [[ $CFLAGS = *sanitize=memory* ]]; then
  extra_c_flags='-DAOM_MAX_ALLOCABLE_MEMORY=536870912'
else
  extra_c_flags='-DAOM_MAX_ALLOCABLE_MEMORY=1073741824'
fi
extra_c_flags+=' -DDO_RANGE_CHECK_CLAMP=1'
extra_cmake_flags=
if [[ $CFLAGS = *sanitize=memory* ]]; then
  extra_cmake_flags+="-DAOM_TARGET_CPU=generic"
fi
cmake $SRC/aom -DCMAKE_BUILD_TYPE=Release -DCMAKE_C_FLAGS_RELEASE='-O3 -g'   -DCMAKE_CXX_FLAGS_RELEASE='-O3 -g' -DCMAKE_LD_FLAGS_RELEASE='-O3 -g'   -DCONFIG_PIC=1 -DCONFIG_SCALABILITY=0 -DCONFIG_LOWBITDEPTH=1   -DCONFIG_AV1_ENCODER=0 -DENABLE_EXAMPLES=0 -DENABLE_DOCS=0 -DENABLE_TESTS=0   -DCONFIG_SIZE_LIMIT=1 -DDECODE_HEIGHT_LIMIT=12288 -DDECODE_WIDTH_LIMIT=12288   -DAOM_EXTRA_C_FLAGS="${extra_c_flags}"   -DAOM_EXTRA_CXX_FLAGS="${extra_c_flags}" ${extra_cmake_flags}
make -j$(nproc)
popd
$CC $CFLAGS -std=c99 -c   -I$SRC/aom   -I${build_dir}   $SRC/aom/common/ivfdec.c -o ${build_dir}/ivfdec.o
$CC $CFLAGS -std=c99 -c   -I$SRC/aom   -I${build_dir}   $SRC/aom/common/tools_common.c -o ${build_dir}/tools_common.o
fuzzer_src_name=av1_dec_fuzzer
fuzzer_modes=( '' '_threaded' )
for mode in "${fuzzer_modes[@]}"; do
  fuzzer_name=${fuzzer_src_name}${mode}
  $CXX $CXXFLAGS -std=c++11     -DDECODE_MODE${mode}     -I$SRC/aom     -I${build_dir}     -Wl,--start-group     -lFuzzingEngine     $SRC/${fuzzer_src_name}.cc -o $OUT/${fuzzer_name}     ${build_dir}/libaom.a ${build_dir}/ivfdec.o ${build_dir}/tools_common.o     -Wl,--end-group
  cp $SRC/dec_fuzzer_seed_corpus.zip $OUT/${fuzzer_name}_seed_corpus.zip
  cp $SRC/av1_dec_fuzzer.dict $OUT/${fuzzer_name}.dict
done
---fuzzer---
// Fuzzing of AV1 decoder.

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <memory>

#include "aom/aom_decoder.h"
#include "aom/aomdx.h"
#include "aom_ports/mem_ops.h"
#include "common/ivfdec.h"

static const char *const kIVFSignature = "DKIF";

static void close_file(FILE *file) { fclose(file); }

extern "C" void usage_exit(void) { exit(EXIT_FAILURE); }

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
  std::unique_ptr<FILE, decltype(&close_file)> file(
      fmemopen((void *)data, size, "rb"), &close_file);
  if (file == nullptr) {
    return 0;
  }

  char header[32];
  if (fread(header, 1, 32, file.get()) != 32) {
    return 0;
  }
  const AvxInterface *decoder = get_aom_decoder_by_name("av1");
  if (decoder == nullptr) {
    return 0;
  }

  aom_codec_ctx_t codec;
#if defined(DECODE_MODE)
  const int threads = 1;
#elif defined(DECODE_MODE_threaded)
  const int threads = 16;
#else
#error define one of DECODE_MODE or DECODE_MODE_threaded
#endif
  aom_codec_dec_cfg_t cfg = {threads, 0, 0};
  if (aom_codec_dec_init(&codec, decoder->codec_interface(), &cfg, 0)) {
    return 0;
  }

  int frame_in_cnt = 0;
  int frame_out_cnt = 0;
  uint8_t *buffer = nullptr;
  size_t buffer_size = 0;
  size_t frame_size = 0;
  while (!ivf_read_frame(file.get(), &buffer, &frame_size, &buffer_size,
                         nullptr)) {
    const aom_codec_err_t err =
        aom_codec_decode(&codec, buffer, frame_size, nullptr);
    ++frame_in_cnt;
    aom_codec_iter_t iter = nullptr;
    aom_image_t *img = nullptr;
    while ((img = aom_codec_get_frame(&codec, &iter)) != nullptr) {
      ++frame_out_cnt;
    }
  }
  aom_codec_destroy(&codec);
  free(buffer);
  return 0;
}
